import copy, re, zipfile, io
from difflib import SequenceMatcher
from lxml import etree
W="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
def q(t): return "{%s}%s"%(W,t)
XML_SPACE="{http://www.w3.org/XML/1998/namespace}space"
AUTHOR="Hargrove, Stern & Whitfield LLP"
DATE="2025-04-14T09:00:00Z"
class Engine:
    def __init__(self, src):
        self.src=src
        z=zipfile.ZipFile(src); self.files={n:z.read(n) for n in z.namelist()}
        self.root=etree.fromstring(self.files["word/document.xml"])
        self.body=self.root.find(q("body"))
        self.paras=[p for p in self.body if p.tag==q("p")]
        self.rid=1000; self.cid=0; self.comments=[]
    def nid(self):
        self.rid+=1; return str(self.rid)
    def _rev(self, tag):
        e=etree.Element(q(tag)); e.set(q("id"),self.nid()); e.set(q("author"),AUTHOR); e.set(q("date"),DATE); return e
    def _run(self, text, rpr, deleted=False):
        r=etree.Element(q("r"))
        if rpr is not None: r.append(copy.deepcopy(rpr))
        t=etree.SubElement(r, q("delText" if deleted else "t")); t.set(XML_SPACE,"preserve"); t.text=text
        return r
    def text(self,i):
        return "".join(t.text or "" for t in self.paras[i].iter(q("t")))
    def mod(self, i, repls, comment=None):
        p=self.paras[i]
        runs=[r for r in p if r.tag==q("r")]
        old="".join("".join(t.text or "" for t in r.iter(q("t"))) for r in runs)
        new=old
        for a,b in repls:
            assert new.count(a)==1, ("not unique/absent", i, a, new.count(a))
            new=new.replace(a,b)
        bounds=[]; pos=0
        for r in runs:
            l=len("".join(t.text or "" for t in r.iter(q("t")))); bounds.append((pos,pos+l,r.find(q("rPr")))); pos+=l
        def rpr_at(c):
            for s,e,rp in bounds:
                if s<=c<e: return rp
            return bounds[-1][2]
        def segs(s,e):
            out=[]
            for bs,be,rp in bounds:
                a=max(s,bs); b=min(e,be)
                if a<b: out.append((a,b,rp))
            return out
        tok=lambda s: re.findall(r"\s+|\w+|[^\w\s]", s)
        ot=tok(old); nt=tok(new)
        ooff=[0]
        for t in ot: ooff.append(ooff[-1]+len(t))
        sm=SequenceMatcher(None, ot, nt, autojunk=False)
        for r in runs: p.remove(r)
        out=[]
        for tag,i1,i2,j1,j2 in sm.get_opcodes():
            s,e=ooff[i1],ooff[i2]
            if tag=="equal":
                for a,b,rp in segs(s,e): out.append(self._run(old[a:b],rp))
            if tag in ("delete","replace"):
                for a,b,rp in segs(s,e):
                    d=self._rev("del"); d.append(self._run(old[a:b],rp,True)); out.append(d)
            if tag in ("insert","replace"):
                ins=self._rev("ins"); ins.append(self._run("".join(nt[j1:j2]), rpr_at(s))); out.append(ins)
        for el in out: p.append(el)
        if comment: self._comment(p, comment)
        return p
    def new_para(self, tmpl_i, label, body):
        t=self.paras[tmpl_i]
        p=etree.Element(q("p"))
        ppr=copy.deepcopy(t.find(q("pPr")))
        if ppr is None: ppr=etree.Element(q("pPr"))
        for x in ppr.findall(q("rPr")): ppr.remove(x)
        rpr=etree.SubElement(ppr,q("rPr")); rpr.append(self._rev("ins"))
        p.append(ppr)
        truns=[r for r in t if r.tag==q("r")]
        ins=self._rev("ins")
        if label:
            ins.append(self._run(label, truns[0].find(q("rPr"))))
            ins.append(self._run(body, truns[-1].find(q("rPr"))))
        else:
            ins.append(self._run(body, truns[-1].find(q("rPr"))))
        p.append(ins)
        return p
    def insert_after(self, i, items):
        """items: list of (tmpl_i, label, body, comment)"""
        anchor=self.paras[i]
        # skip past previously inserted paragraphs after this anchor
        while getattr(anchor,"_ins_tail",None) is not None: anchor=anchor._ins_tail
        prev=self.paras[i]
        last=self._last.get(i, prev)
        for it in items:
            tmpl,label,body=it[:3]; com=it[3] if len(it)>3 else None
            np=self.new_para(tmpl,label,body)
            last.addnext(np); last=np
            if com: self._comment(np, com)
        self._last[i]=last
    _last={}
    def delete_para(self, i, comment=None):
        p=self.paras[i]
        ppr=p.find(q("pPr"))
        rpr=ppr.find(q("rPr"))
        if rpr is None: rpr=etree.SubElement(ppr,q("rPr"))
        rpr.append(self._rev("del"))
        for r in [r for r in p if r.tag==q("r")]:
            for t in r.findall(q("t")): t.tag=q("delText")
            d=self._rev("del"); r.addprevious(d); d.append(r)
        if comment: self._comment(p, comment)
    def _comment(self, p, text):
        cid=str(self.cid); self.cid+=1
        s=etree.Element(q("commentRangeStart")); s.set(q("id"),cid)
        ppr=p.find(q("pPr"))
        if ppr is not None: ppr.addnext(s)
        else: p.insert(0,s)
        e=etree.SubElement(p,q("commentRangeEnd")); e.set(q("id"),cid)
        r=etree.SubElement(p,q("r")); rpr=etree.SubElement(r,q("rPr")); rs=etree.SubElement(rpr,q("rStyle")); rs.set(q("val"),"CommentReference")
        cr=etree.SubElement(r,q("commentReference")); cr.set(q("id"),cid)
        self.comments.append((cid,text))
    def save(self, out):
        self.files["word/document.xml"]=etree.tostring(self.root, xml_declaration=True, encoding="UTF-8", standalone=True)
        if self.comments:
            croot=etree.Element(q("comments"), nsmap={"w":W})
            for cid,text in self.comments:
                c=etree.SubElement(croot,q("comment")); c.set(q("id"),cid); c.set(q("author"),"HSW Internal Note"); c.set(q("initials"),"HSW"); c.set(q("date"),DATE)
                for k,para in enumerate(text.split("\n")):
                    pp=etree.SubElement(c,q("p"))
                    if k==0:
                        rr=etree.SubElement(pp,q("r")); rp=etree.SubElement(rr,q("rPr")); rs=etree.SubElement(rp,q("rStyle")); rs.set(q("val"),"CommentReference"); etree.SubElement(rr,q("annotationRef"))
                    rr=etree.SubElement(pp,q("r")); t=etree.SubElement(rr,q("t")); t.set(XML_SPACE,"preserve"); t.text=para
            self.files["word/comments.xml"]=etree.tostring(croot, xml_declaration=True, encoding="UTF-8", standalone=True)
            ct=self.files["[Content_Types].xml"].decode()
            if "/word/comments.xml" not in ct:
                ct=ct.replace("</Types>",'<Override PartName="/word/comments.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml"/></Types>')
                self.files["[Content_Types].xml"]=ct.encode()
            rels=self.files["word/_rels/document.xml.rels"].decode()
            if "relationships/comments" not in rels:
                rels=rels.replace("</Relationships>",'<Relationship Id="rIdHSWComments" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments" Target="comments.xml"/></Relationships>')
                self.files["word/_rels/document.xml.rels"]=rels.encode()
        st=self.files["word/settings.xml"].decode()
        if "trackRevisions" not in st:
            st=re.sub(r"(<w:settings[^>]*>)", r"\1<w:trackRevisions/>", st, count=1)
            self.files["word/settings.xml"]=st.encode()
        with zipfile.ZipFile(out,"w",zipfile.ZIP_DEFLATED) as z:
            for n,b in self.files.items(): z.writestr(n,b)
